   * Who advertised: the homelab-ai gateway contract, a vLLM-style catalog, a server's own endpoint for its loaded
   * context (llama.cpp `/props`, LM Studio `/api/v0/models`, Ollama `/api/show`), or an OpenAI-style catalog with no limits.
   */
  via: "aihost_gateway" | "vllm" | "llamacpp" | "lmstudio" | "ollama" | "catalog";
  serverKind?: ServerKind;
  /** null: the provider says the capacity is currently unknown (e.g. no serving worker observed). */
  contextLength?: number | null;
  maxCompletionTokens?: number;
  limitsVersion?: string;
  reasoning?: { mode?: string; budget?: number };
  workers?: string[];
  /** The connection's contract includes a request-counting endpoint (/v1/tokenize). */
  tokenize: boolean;
}

export interface ProviderCapabilities {
  model: string;
  observedAt: string;
  discovery: CapabilityState;
  discoveryDetail?: string;
  advertised?: Advertisement;
  if (!body || typeof body !== "object" || Array.isArray(body)) return undefined;
  const version = (body as Record<string, unknown>).version;
  return typeof version === "string" && version.trim().length > 0 ? version.trim() : undefined;
}

export function serverKindOfAdvertisement(ad: Advertisement | undefined): ServerKind {
  if (!ad) return "unknown";
  if (ad.via === "aihost_gateway") return "gateway";
  if (ad.via === "vllm") return "vllm";
  if (ad.via === "llamacpp") return "llamacpp";
  if (ad.via === "lmstudio") return "lmstudio";
  if (ad.via === "ollama") return "ollama";
  return "unknown";
}

/** Reads one `/models` entry. Unknown shapes yield a catalog advertisement with no limits (never an error). */
export function parseAdvertisement(entry: Record<string, any> | undefined): Advertisement | undefined {
  if (!entry || typeof entry !== "object") return undefined;
  const gateway = typeof entry.limits_version === "string" && entry.limits_version.length > 0;
  const workers = Array.isArray(entry.serving)
    ? entry.serving.map((s: any) => (typeof s?.worker_id === "string" ? s.worker_id : undefined)).filter((w: string | undefined): w is string => Boolean(w)).sort()
    : undefined;
  const contextLength = entry.context_length === null ? null : positiveInt(entry.context_length) ?? positiveInt(entry.max_model_len);
  const reasoning = entry.reasoning && typeof entry.reasoning === "object"
    ? { ...(typeof entry.reasoning.mode === "string" ? { mode: entry.reasoning.mode } : {}), ...(positiveInt(entry.reasoning.budget) ? { budget: positiveInt(entry.reasoning.budget) } : {}) }
    : undefined;
  return {
    via: gateway ? "aihost_gateway" : "catalog",
    ...(contextLength !== undefined ? { contextLength } : {}),
    ...(positiveInt(entry.max_completion_tokens) ? { maxCompletionTokens: positiveInt(entry.max_completion_tokens) } : {}),
    ...(gateway ? { limitsVersion: entry.limits_version } : {}),
    ...(reasoning && Object.keys(reasoning).length ? { reasoning } : {}),
    ...(workers?.length ? { workers } : {}),
    tokenize: gateway,
  };
}

/**
 * The context a local server says it has loaded, from its own endpoint (REQ-PRV-101): llama.cpp `GET /props`
 * (default_generation_settings.n_ctx: the runtime window, not the model's training size), LM Studio `GET /api/v0/models`
 * (loaded_context_length, else max_context_length), Ollama `POST /api/show` (the num_ctx parameter, else the model's
  async discoverAdvertisement(signal?: AbortSignal): Promise<{ state: "supported" | "unsupported" | "unavailable"; advertised?: Advertisement; detail?: string }> {
    const ep = this.endpoint;
    const previousKind = LocalLlmClient.serverKindCache.get(this.kindKey(ep));
    // A catalog that cannot speak for itself (404, model unlisted) keeps a verified server identity, except a gateway:
    // the gateway-only task-class header must follow positive evidence, not a replaced server's silence (REQ-PRV-109).
    const retainedKind = previousKind === "gateway" ? undefined : previousKind;
    this.everDiscovered = true;
    let retained = false;
    const remember = (kind: ServerKind): void => {
      if (retained && kind === previousKind) return; // retained without new evidence: do not extend the TTL
      LocalLlmClient.serverKindCache.set(this.kindKey(ep), kind);
    };
    if (this.conn.protocol !== "openai-chat") return { state: "unsupported", detail: `${this.conn.protocol} connection` };
    const url = `${ep}/models`;
    try {
      await this.prepareCredential(ep);
      const res = await fetch(url, {
        // Marked so providers (and their logs) can tell a capability read from an availability probe.
        headers: { ...this.authorization(url), "X-Nexus-Purpose": "capabilities" },
        signal: signal ? AbortSignal.any([signal, AbortSignal.timeout(10_000)]) : AbortSignal.timeout(10_000),
        ...this.fetchPolicy(),
      });
      if (res.status === 404) {
